@Component("claimPayment-handler")
@ProcessingGroup("claimPayment-processing-group")
public class ClaimPaymentEventHandler {
	
	// core constructor
	ClaimPaymentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateClaimPaymentEvent
     */
    @EventHandler
    public void handle( CreateClaimPaymentEvent event) {
        entityManager.persist(new ClaimPayment(event.getClaimPaymentId(), event.getPaymentNumber(), event.getAmount(), event.getPaymentDate(), event.getClaim(), event.getExposure(), event.getBeneficiary(), event.getServiceProvider(), event.getCustomer(), event.getPayeeType(), event.getMethod(), event.getStatus()));
    }

    /*
     * @param	event UpdateClaimPaymentEvent
     */
    @EventHandler
    public ClaimPayment handle( UpdateClaimPaymentEvent event) {
    	entityManager.merge(new ClaimPayment(event.getClaimPaymentId(), event.getPaymentNumber(), event.getAmount(), event.getPaymentDate(), event.getClaim(), event.getExposure(), event.getBeneficiary(), event.getServiceProvider(), event.getCustomer(), event.getPayeeType(), event.getMethod(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteClaimPaymentEvent
     */
    @EventHandler
    public void on( DeleteClaimPaymentEvent event) {
    	ClaimPayment entity = new ClaimPayment();
   
    	// ------------------------------------------
    	// apply the ClaimPaymentId
    	// ------------------------------------------
    	entity.setClaimPaymentId( event.getClaimPaymentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ClaimPaymentRepository claimPaymentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ClaimPaymentEventHandler.class.getName());

}
